-- PROFILES
ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name, email=EXCLUDED.email, room_number=EXCLUDED.room_number, block_name=EXCLUDED.block_name, bed_number=EXCLUDED.bed_number, roll_no=EXCLUDED.roll_no, fee_status=EXCLUDED.fee_status, fee_amount_due=EXCLUDED.fee_amount_due, attendance_percent=EXCLUDED.attendance_percent;

-- ROOMS
ON CONFLICT (id) DO UPDATE SET block_id=EXCLUDED.block_id, block_name=EXCLUDED.block_name, floor=EXCLUDED.floor, type=EXCLUDED.type, capacity=EXCLUDED.capacity, occupied=EXCLUDED.occupied, status=EXCLUDED.status, amenities=EXCLUDED.amenities, occupants=EXCLUDED.occupants;